def lbs(arr):
    n = len(arr)
    # Initialize dp arrays
    inc = [1] * n
    dec = [1] * n

    # Fill up the inc array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill up the dec array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum length of the bitonic subsequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, inc[i] + dec[i] - 1)

    return max_length
```

